component.css:
.template-player {
  border: 1px solid #6366f1;
  border-radius: 18px;
  padding: 16px;
  background: linear-gradient(180deg, #0f0f1a, #1a1a2e);
  color: #e0e0f0;
  max-width: 100%;
  box-shadow: 0 8px 32px rgba(99, 102, 241, 0.15);
}

.template-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.template-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  border-radius: 8px;
  font-size: 12px;
  color: #fff;
}

.template-title {
  font-weight: 700;
  font-size: 15px;
  color: #c7d2fe;
  letter-spacing: 0.3px;
}

.template-desc {
  margin-top: 10px;
  font-size: 13px;
  color: #94a3b8;
  padding: 8px 12px;
  background: rgba(99, 102, 241, 0.08);
  border-radius: 8px;
  border-left: 3px solid #6366f1;
}

.template-actions {
  margin-top: 12px;
  display: flex;
  gap: 8px;
}

.btn-copy {
  padding: 6px 16px;
  border-radius: 8px;
  border: none;
  background: rgba(99, 102, 241, 0.15);
  color: #a5b4fc;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-copy:hover {
  background: rgba(99, 102, 241, 0.3);
}

component.script:
const desc = '$说明文字$'
if (desc && desc.trim() !== '' && desc.trim() !== '$说明文字$') {
  setText('[data-desc]', desc)
  show('[data-desc]')
}



setValue('#template-video', '$视频地址$')
setValue('#video-source', '$视频地址$')







const btn = document.querySelector('[data-copy-btn]')
if (btn) {
  btn.addEventListener('click', function() {
    const videoSrc = document.getElementById('template-video')?.src || ''
    if (videoSrc) {
      copyText(videoSrc)
      toast('视频链接已复制', 'success')
    } else {
      toast('未找到视频地址', 'error')
    }
  })
}
